/*
 * Thin Microsoft Graph helpers: sites, libraries, folders, uploads and mail.
 */

/* global fetch, setTimeout, Blob */

import { getAccessToken } from "./signin";
import { GRAPH_SCOPES, SHARED_MAILBOX_SCOPES } from "../config";

const GRAPH = "https://graph.microsoft.com/v1.0";
const SIMPLE_UPLOAD_LIMIT = 4 * 1024 * 1024; // Graph's limit for a single PUT
const CHUNK_SIZE = 320 * 1024 * 10; // upload-session chunks must be multiples of 320 KiB

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function request(
  url,
  { method = "GET", body, headers = {}, auth = true, raw = false, scopes = GRAPH_SCOPES } = {}
) {
  const fullUrl = url.startsWith("https://") ? url : GRAPH + url;

  for (let attempt = 0; ; attempt++) {
    const allHeaders = { ...headers };
    if (auth) allHeaders.Authorization = `Bearer ${await getAccessToken(scopes)}`;

    const res = await fetch(fullUrl, { method, headers: allHeaders, body });

    // Back off and retry when Graph throttles us or is briefly unavailable.
    if ((res.status === 429 || res.status === 503 || res.status === 504) && attempt < 4) {
      const retryAfter = Number(res.headers.get("Retry-After")) || 2 ** attempt;
      await sleep(retryAfter * 1000);
      continue;
    }

    if (!res.ok) {
      let message = `${res.status} ${res.statusText}`;
      try {
        const json = await res.json();
        if (json?.error?.message) message = json.error.message;
      } catch {
        /* body wasn't JSON */
      }
      const error = new Error(message);
      error.status = res.status;
      throw error;
    }

    if (raw) return res;
    if (res.status === 204 || res.status === 202) return null;
    const text = await res.text();
    return text ? JSON.parse(text) : null;
  }
}

async function getAll(url) {
  const items = [];
  let next = url;
  while (next) {
    const page = await request(next);
    items.push(...(page.value || []));
    next = page["@odata.nextLink"];
  }
  return items;
}

const enc = encodeURIComponent;

/* ---------- Sites, libraries, folders ---------- */

export function getFollowedSites() {
  return getAll("/me/followedSites?$select=id,displayName,webUrl");
}

export async function searchSites(query) {
  const page = await request(`/sites?search=${enc(query)}&$select=id,displayName,webUrl&$top=25`);
  return page.value || [];
}

export async function getLibraries(siteId) {
  const drives = await getAll(`/sites/${enc(siteId)}/drives?$select=id,name,driveType,webUrl`);
  return drives.filter((d) => d.driveType === "documentLibrary");
}

export async function getFolders(driveId, folderId) {
  const base = folderId
    ? `/drives/${enc(driveId)}/items/${enc(folderId)}`
    : `/drives/${enc(driveId)}/root`;
  const children = await getAll(`${base}/children?$select=id,name,folder&$top=500`);
  return children.filter((c) => c.folder).sort((a, b) => a.name.localeCompare(b.name));
}

export function createFolder(driveId, parentId, name) {
  const base = parentId
    ? `/drives/${enc(driveId)}/items/${enc(parentId)}`
    : `/drives/${enc(driveId)}/root`;
  return request(`${base}/children`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name, folder: {}, "@microsoft.graph.conflictBehavior": "rename" }),
  });
}

/* ---------- Uploads ---------- */

function itemPath(driveId, parentId, fileName) {
  const parent = parentId
    ? `/drives/${enc(driveId)}/items/${enc(parentId)}`
    : `/drives/${enc(driveId)}/root`;
  return `${parent}:/${enc(fileName)}:`;
}

/** Uploads a file; if the name is taken, SharePoint adds " 1", " 2" etc. */
export async function uploadFile(driveId, parentId, fileName, blob) {
  const path = itemPath(driveId, parentId, fileName);

  if (blob.size <= SIMPLE_UPLOAD_LIMIT) {
    return request(`${path}/content?@microsoft.graph.conflictBehavior=rename`, {
      method: "PUT",
      headers: { "Content-Type": "message/rfc822" },
      body: blob,
    });
  }

  // Large emails: resumable upload session.
  const session = await request(`${path}/createUploadSession`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ item: { "@microsoft.graph.conflictBehavior": "rename" } }),
  });

  let result = null;
  for (let start = 0; start < blob.size; start += CHUNK_SIZE) {
    const end = Math.min(start + CHUNK_SIZE, blob.size);
    // The upload URL is pre-authenticated; sending a bearer token here is rejected.
    result = await request(session.uploadUrl, {
      method: "PUT",
      auth: false,
      headers: { "Content-Range": `bytes ${start}-${end - 1}/${blob.size}` },
      body: blob.slice(start, end),
    });
  }
  return result;
}

/* ---------- Mail ---------- */

// `mailbox` is null for the user's own mailbox, or a shared mailbox's email address.
// Shared mailboxes need the extra Mail.ReadWrite.Shared permission, so it's only
// requested when one is actually used.
function mailBase(mailbox) {
  return mailbox ? `/users/${enc(mailbox)}` : "/me";
}
function mailScopes(mailbox) {
  return mailbox ? SHARED_MAILBOX_SCOPES : GRAPH_SCOPES;
}

export function getMessageInfo(messageId, mailbox = null) {
  return request(
    `${mailBase(mailbox)}/messages/${enc(messageId)}?$select=subject,receivedDateTime,sentDateTime,from`,
    { scopes: mailScopes(mailbox) }
  );
}

/** The full email as MIME (.eml), including attachments. */
export async function getMessageMime(messageId, mailbox = null) {
  const res = await request(`${mailBase(mailbox)}/messages/${enc(messageId)}/$value`, {
    raw: true,
    scopes: mailScopes(mailbox),
  });
  return new Blob([await res.arrayBuffer()], { type: "message/rfc822" });
}

/** Moves to that mailbox's Deleted Items (recoverable), rather than deleting permanently. */
export function moveToDeletedItems(messageId, mailbox = null) {
  return request(`${mailBase(mailbox)}/messages/${enc(messageId)}/move`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ destinationId: "deleteditems" }),
    scopes: mailScopes(mailbox),
  });
}
