/*
 * Sign-in using Nested App Authentication (NAA) via MSAL.js.
 * Office brokers the sign-in, so users are normally signed in silently with
 * the same account they use in Outlook. A popup is used only when consent
 * or extra sign-in is required.
 */

/* global window, URL */

import { createNestablePublicClientApplication } from "@azure/msal-browser";
import { CLIENT_ID, TENANT_ID, GRAPH_SCOPES } from "../config";

let pcaPromise = null;

function getClient() {
  if (!pcaPromise) {
    pcaPromise = createNestablePublicClientApplication({
      auth: {
        clientId: CLIENT_ID,
        authority: `https://login.microsoftonline.com/${TENANT_ID}`,
        // Only used if NAA is unavailable and MSAL falls back to a browser popup.
        redirectUri: new URL("auth.html", window.location.href).href, // works when hosted in a sub-folder too
      },
      cache: { cacheLocation: "localStorage" },
    });
  }
  return pcaPromise;
}

export async function getAccessToken(scopes = GRAPH_SCOPES) {
  const pca = await getClient();
  const account = pca.getActiveAccount() || pca.getAllAccounts()[0];
  const request = account ? { scopes, account } : { scopes };

  try {
    const result = await pca.acquireTokenSilent(request);
    if (result.account) pca.setActiveAccount(result.account);
    return result.accessToken;
  } catch {
    // Fall through to interactive sign-in (first run, consent needed, etc.).
  }

  const result = await pca.acquireTokenPopup({ scopes });
  pca.setActiveAccount(result.account);
  return result.accessToken;
}
