/*
 * Settings you must fill in before running the add-in.
 * See README.md, "1. Register the app in Microsoft Entra ID".
 */

// Application (client) ID of your Entra app registration.
export const CLIENT_ID = "af512e22-744b-4f90-bee4-cb42271f6175";

// Directory (tenant) ID of your Microsoft 365 tenant.
export const TENANT_ID = "ed1644c5-05e0-49e6-bc39-fcf7ac51c18c";

// Microsoft Graph permissions the add-in asks for (delegated).
// Mail.ReadWrite      - read the email's content and move it to Deleted Items.
// Sites.ReadWrite.All - browse sites/libraries and upload files. Needs admin consent.
export const GRAPH_SCOPES = ["Mail.ReadWrite", "Sites.ReadWrite.All"];

// Extra permission used only when saving from a shared mailbox. Needs admin consent.
export const SHARED_MAILBOX_SCOPES = [...GRAPH_SCOPES, "Mail.ReadWrite.Shared"];

// What the "Remove from mailbox after saving" box is set to the first time someone uses the add-in.
export const REMOVE_FROM_MAILBOX_BY_DEFAULT = true;
