/*
 * Save to SharePoint – task pane logic.
 */

/* global document, Office, window, setTimeout, clearTimeout */

import * as graph from "./graph";
import { REMOVE_FROM_MAILBOX_BY_DEFAULT } from "../config";

const $ = (id) => document.getElementById(id);

const state = {
  selection: [], // [{ itemId (EWS), subject }]
  destination: null, // { siteId, siteName, driveId, driveName, folderId, folderPath: [names] }
  saving: false,
  sharedMailboxes: [], // shared mailbox addresses the user has added or the add-in has learned
  picker: { step: null, site: null, drive: null, folderStack: [] }, // folderStack: [{id, name}]
};

/* ---------- Start-up ---------- */

let started = false;

// Show any start-up problem inside the pane, so it can be screenshotted.
function showStartupProblem(text) {
  if (started) return;
  const box = $("sideload-msg");
  box.hidden = false;
  box.textContent = text;
}

window.addEventListener("error", (e) => {
  showStartupProblem(
    `Start-up error: ${e.message || e.error} (${e.filename || "unknown file"}:${e.lineno || "?"})`
  );
});
window.addEventListener("unhandledrejection", (e) => {
  showStartupProblem(`Start-up error: ${(e.reason && e.reason.message) || e.reason}`);
});

setTimeout(() => {
  const inOutlook = typeof Office !== "undefined" && Office.context && Office.context.mailbox;
  showStartupProblem(
    inOutlook
      ? "Outlook connected, but the add-in didn't finish starting. Close the pane and reopen it."
      : `Office.js didn't connect to Outlook. Details: ${window.location.href} | host info in URL: ${/_host_Info/i.test(
          window.location.href
        )} | Office loaded: ${typeof Office !== "undefined"}`
  );
}, 10000);

Office.onReady((info) => {
  // Start whenever we're in Outlook. Checking for a mailbox is more reliable than
  // the host name, which some Outlook versions report differently.
  if (!(Office.context && Office.context.mailbox)) {
    showStartupProblem(`Not running inside Outlook (host reported: ${info && info.host}).`);
    return;
  }
  started = true;
  $("sideload-msg").hidden = true;
  $("app").hidden = false;

  state.destination = getSetting("destination", null);
  $("remove-after").checked = getSetting("removeAfter", REMOVE_FROM_MAILBOX_BY_DEFAULT);
  $("remove-after").addEventListener("change", (e) => setSetting("removeAfter", e.target.checked));

  $("change-destination").addEventListener("click", () => openPicker());
  $("save").addEventListener("click", saveSelected);
  $("picker-back").addEventListener("click", pickerBack);
  $("site-search").addEventListener("submit", onSiteSearch);
  $("new-folder").addEventListener("click", onNewFolder);
  $("choose-folder").addEventListener("click", onChooseFolder);

  state.sharedMailboxes = getSetting("sharedMailboxes", []);
  $("shared-form").addEventListener("submit", onAddSharedMailbox);
  renderSharedMailboxes();

  // Keep the pane in sync when the user selects other emails. Which events are
  // available depends on the manifest and Outlook version, so each is optional.
  const mailbox = Office.context.mailbox;
  tryAddHandler(mailbox, Office.EventType.SelectedItemsChanged);
  tryAddHandler(mailbox, Office.EventType.ItemChanged);

  renderDestination();
  loadSelection();
});

/* ---------- Roaming settings (follow the user across devices) ---------- */

function getSetting(name, fallback) {
  const value = Office.context.roamingSettings.get(name);
  return value === undefined || value === null ? fallback : value;
}

function setSetting(name, value) {
  Office.context.roamingSettings.set(name, value);
  Office.context.roamingSettings.saveAsync();
}

/* ---------- Selected emails ---------- */

function tryAddHandler(mailbox, eventType) {
  if (!eventType) return;
  try {
    mailbox.addHandlerAsync(
      eventType,
      () => loadSelection(),
      () => {}
    );
  } catch {
    /* not supported here - fine */
  }
}

function loadSelection() {
  // The open email is always available in reading mode; show it straight away.
  const single = currentItemOnly();
  setSelection(single);

  // Where Outlook supports selecting several emails, ask for the full selection too.
  if (!Office.context.requirements.isSetSupported("Mailbox", "1.13")) return;
  try {
    Office.context.mailbox.getSelectedItemsAsync((result) => {
      if (result.status !== Office.AsyncResultStatus.Succeeded) {
        if (!single.length) {
          $("selection-summary").textContent =
            "Couldn't read the selected emails: " +
            ((result.error && result.error.message) || "unknown error");
        }
        return;
      }
      // Multi-select only ever returns messages, and some Outlook versions label
      // the item type differently, so take every item rather than filtering on it.
      const items = (result.value || [])
        .filter((i) => i && i.itemId)
        .map((i) => ({ itemId: i.itemId, subject: i.subject }));
      if (items.length) setSelection(items);
    });
  } catch (error) {
    if (!single.length) {
      $("selection-summary").textContent =
        "Couldn't read the selected emails: " + (error.message || error);
    }
  }
}

function currentItemOnly() {
  const item = Office.context.mailbox.item;
  return item && item.itemId ? [{ itemId: item.itemId, subject: item.subject }] : [];
}

function setSelection(items) {
  if (state.saving) return; // don't swap the list out from under an in-progress save
  state.selection = items;
  const list = $("selection-list");
  list.replaceChildren();

  if (!items.length) {
    $("selection-summary").textContent = "Select one or more emails to save.";
  } else {
    $("selection-summary").textContent =
      items.length === 1 ? "1 email selected" : `${items.length} emails selected`;
    for (const item of items) {
      const li = el("li", null, item.subject || "(no subject)");
      li.title = item.subject || "";
      list.append(li);
    }
  }
  // Results from the last save stay visible: moving emails changes the selection,
  // and clearing here would wipe the outcome the user just waited for.
  updateSaveButton();
}

function toRestId(ewsId) {
  return Office.context.mailbox.convertToRestId(ewsId, Office.MailboxEnums.RestVersion.v2_0);
}

/* ---------- Which mailbox are the emails in? ---------- */

// Runs an Office.js callback-style call as a promise, giving up after `ms`.
function officeCall(start, ms = 5000) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve(null), ms);
    try {
      start((result) => {
        clearTimeout(timer);
        resolve(result);
      });
    } catch {
      clearTimeout(timer);
      resolve(null);
    }
  });
}

// Asks Outlook whether `item` is in a shared mailbox.
// Returns the mailbox's addresses, or null if Outlook doesn't say (which is also what
// happens for the user's own mailbox, so null is never treated as "definitely personal").
async function sharedAddressesFor(item) {
  if (!item || typeof item.getSharedPropertiesAsync !== "function") return null;
  const result = await officeCall((cb) => item.getSharedPropertiesAsync(cb));
  if (!result) return null;
  if (result.status !== Office.AsyncResultStatus.Succeeded || !result.value) return null;

  const mine = ((Office.context.mailbox.userProfile || {}).emailAddress || "").toLowerCase();
  const seen = new Set();
  return [result.value.owner, result.value.targetMailbox]
    .filter((a) => typeof a === "string" && a.includes("@"))
    .filter(
      (a) => a.toLowerCase() !== mine && !seen.has(a.toLowerCase()) && seen.add(a.toLowerCase())
    );
}

/**
 * Works out which mailbox to read the selected emails from. Outlook only allows
 * selecting emails from one mailbox at a time, so checking one email is enough.
 * Returns the mailboxes to try in order: null means the user's own mailbox.
 */
async function mailboxesToTry(items) {
  const mailbox = Office.context.mailbox;
  const first = items[0];
  let shared = null;

  // The open email (single selection).
  if (mailbox.item && mailbox.item.itemId === first.itemId) {
    shared = await sharedAddressesFor(mailbox.item);
  }

  // Several emails selected: load one of them to ask (Mailbox 1.15+).
  if (!shared && typeof mailbox.loadItemByIdAsync === "function") {
    const loaded = await officeCall((cb) => mailbox.loadItemByIdAsync(first.itemId, cb));
    if (loaded && loaded.status === Office.AsyncResultStatus.Succeeded && loaded.value) {
      shared = await sharedAddressesFor(loaded.value);
      if (typeof loaded.value.unloadAsync === "function") {
        await officeCall((cb) => loaded.value.unloadAsync(cb));
      }
    }
  }

  const known = state.sharedMailboxes.filter((m) => !(shared || []).includes(m));
  if (shared && shared.length) {
    rememberSharedMailbox(shared[0]);
    return [...shared, null, ...known];
  }
  // Outlook didn't say: try the user's own mailbox, then any shared mailboxes we know.
  return [null, ...known];
}

const NOT_HERE =
  /doesn't belong to the targeted mailbox|not found in the store|ErrorItemNotFound|ResourceNotFound/i;

/** Reads the email's details from the first mailbox that has it, and returns that mailbox. */
async function findMessage(restId, candidates) {
  let denied = null;
  for (const mailbox of candidates) {
    try {
      const info = await graph.getMessageInfo(restId, mailbox);
      if (mailbox) rememberSharedMailbox(mailbox);
      return { info, mailbox };
    } catch (error) {
      const notHere = error.status === 404 || NOT_HERE.test(error.message || "");
      if (notHere) continue;
      // No access to this shared mailbox: keep looking, but report it if nothing else works.
      if (mailbox && error.status === 403) {
        denied = denied || error;
        continue;
      }
      throw error; // sign-in/consent problems and anything unexpected
    }
  }
  if (denied) throw denied;
  const error = new Error(
    "This email isn't in your own mailbox or any shared mailbox the add-in knows about."
  );
  error.status = 404;
  error.needsSharedAddress = true;
  throw error;
}

/* ---------- Shared mailboxes list ---------- */

function rememberSharedMailbox(address) {
  if (!address) return;
  const exists = state.sharedMailboxes.some((m) => m.toLowerCase() === address.toLowerCase());
  if (exists) return;
  state.sharedMailboxes = [...state.sharedMailboxes, address];
  setSetting("sharedMailboxes", state.sharedMailboxes);
  renderSharedMailboxes();
}

function renderSharedMailboxes() {
  const list = $("shared-list");
  list.replaceChildren();
  for (const address of state.sharedMailboxes) {
    const remove = el("button", "link-button", "Remove");
    remove.type = "button";
    remove.addEventListener("click", () => {
      state.sharedMailboxes = state.sharedMailboxes.filter((m) => m !== address);
      setSetting("sharedMailboxes", state.sharedMailboxes);
      renderSharedMailboxes();
    });
    list.append(el("li", null, [el("span", null, address), remove]));
  }
  const n = state.sharedMailboxes.length;
  $("shared-summary").textContent = n ? `Shared mailboxes (${n})` : "Shared mailboxes";
}

function onAddSharedMailbox(event) {
  event.preventDefault();
  const input = $("shared-input");
  const address = input.value.trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address)) {
    showMessage("Enter the shared mailbox's full email address, e.g. team@hmtreasury.gov.uk.");
    return;
  }
  hideMessage();
  rememberSharedMailbox(address);
  input.value = "";
}

/* ---------- Destination ---------- */

function renderDestination() {
  const d = state.destination;
  const box = $("destination-path");
  box.replaceChildren();

  if (!d) {
    box.textContent = "No location chosen yet";
    box.classList.add("muted");
    $("change-destination").textContent = "Choose…";
  } else {
    box.classList.remove("muted");
    box.append(el("strong", null, d.siteName));
    box.append(el("div", null, [d.driveName, ...(d.folderPath || [])].join(" › ")));
    $("change-destination").textContent = "Change";
  }
  updateSaveButton();
}

function updateSaveButton() {
  const n = state.selection.length;
  const button = $("save");
  button.disabled = state.saving || !n || !state.destination;
  const verb = $("remove-after").checked ? "Move" : "Save";
  button.textContent = state.saving
    ? "Saving…"
    : n > 1
      ? `${verb} ${n} emails to SharePoint`
      : `${verb} to SharePoint`;
}
document.addEventListener("change", (e) => {
  if (e.target && e.target.id === "remove-after") updateSaveButton();
});

/* ---------- Saving ---------- */

async function saveSelected() {
  const dest = state.destination;
  const items = [...state.selection];
  const removeAfter = $("remove-after").checked;
  if (!dest || !items.length) return;

  hideMessage();
  state.saving = true;
  updateSaveButton();

  const results = $("results");
  results.replaceChildren();
  const rows = items.map((item) => {
    const status = el("span", "status muted", "•");
    const name = el("span", "name", item.subject || "(no subject)");
    const li = el("li", null, [status, name]);
    results.append(li);
    return { status, name };
  });

  let candidates = [null];
  try {
    candidates = await mailboxesToTry(items);
  } catch {
    /* fall back to the user's own mailbox */
  }

  let saved = 0;
  let needsSharedAddress = false;
  for (let i = 0; i < items.length; i++) {
    const { status, name } = rows[i];
    status.textContent = "…";
    let stage = "read";
    try {
      const id = toRestId(items[i].itemId);
      const { info, mailbox } = await findMessage(id, candidates);
      // Once we know where the emails live, try that mailbox first for the rest.
      candidates = [mailbox, ...candidates.filter((c) => c !== mailbox)];

      const mime = await graph.getMessageMime(id, mailbox);
      stage = "upload";
      const file = await graph.uploadFile(dest.driveId, dest.folderId, buildFileName(info), mime);

      if (removeAfter) {
        stage = "remove";
        await graph.moveToDeletedItems(id, mailbox);
      }

      status.textContent = "✓";
      status.className = "status ok";
      name.replaceChildren(
        file && file.webUrl ? link(file.name, file.webUrl) : el("span", null, file ? file.name : "")
      );
      saved++;
    } catch (error) {
      status.textContent = "✕";
      status.className = "status err";
      name.append(el("div", "small err", friendlyError(error, stage)));
      if (error && error.needsSharedAddress) needsSharedAddress = true;
    }
  }

  state.saving = false;
  updateSaveButton();

  if (needsSharedAddress) {
    $("shared-box").open = true;
    $("shared-input").focus();
  }

  const failed = items.length - saved;
  if (failed)
    showMessage(
      `${failed} of ${items.length} email${items.length > 1 ? "s" : ""} could not be saved. See details above.`
    );
}

/** e.g. "2026-10-06 0914 - Jane Smith - Quarterly report.eml" */
function buildFileName(info) {
  const d = new Date(info.receivedDateTime || info.sentDateTime || Date.now());
  const pad = (n) => String(n).padStart(2, "0");
  const stamp = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}${pad(d.getMinutes())}`;
  const sender =
    info.from?.emailAddress?.name || info.from?.emailAddress?.address || "Unknown sender";
  const subject = info.subject || "(no subject)";

  let base = `${stamp} - ${sender} - ${subject}`
    // eslint-disable-next-line no-control-regex
    .replace(/["*:<>?/\\|\u0000-\u001f]/g, "_") // characters SharePoint doesn't allow
    .replace(/\s+/g, " ")
    .trim();
  if (base.length > 150) base = base.slice(0, 150).trim();
  base = base.replace(/[.\s]+$/, ""); // no trailing dots/spaces
  return `${base}.eml`;
}

function friendlyError(error, stage = "") {
  const msg = (error && error.message) || String(error);
  const status = error && error.status;
  if (/consent|AADSTS65001|admin approval/i.test(msg))
    return "The add-in hasn't been approved for this yet. Ask your IT admin to grant consent (for shared mailboxes: Mail.ReadWrite.Shared).";
  if (/popup/i.test(msg))
    return "Sign-in was blocked or closed. Allow pop-ups for Outlook and try again.";
  if (stage === "upload") {
    if (status === 403)
      return `Access denied. You may not have permission to add files to this library. (${msg})`;
    if (status === 404)
      return `The SharePoint folder wasn't found. It may have been moved or deleted. (${msg})`;
  }
  if (stage === "remove" && status === 403)
    return `Saved to SharePoint, but couldn't remove the email. You may need Full Access to this mailbox. (${msg})`;
  if (status === 403)
    return `Access denied to this mailbox. For a shared mailbox you need Full Access, and the add-in needs the Mail.ReadWrite.Shared permission. (${msg})`;
  if (error && error.needsSharedAddress)
    return "This email looks like it's in a shared mailbox the add-in doesn't know yet. Add the shared mailbox's email address under \"Shared mailboxes\" above, then save again.";
  if (status === 404) return `Email not found. It may have been moved or deleted. (${msg})`;
  return msg;
}

/* ---------- Location picker ---------- */

function showView(name) {
  $("view-main").hidden = name !== "main";
  $("view-picker").hidden = name !== "picker";
  hideMessage();
}

function openPicker() {
  showView("picker");
  showSites();
}

function pickerBack() {
  const p = state.picker;
  if (p.step === "folder" && p.folderStack.length) {
    p.folderStack.pop();
    showFolders();
  } else if (p.step === "folder") {
    showLibraries(p.site);
  } else if (p.step === "library") {
    showSites();
  } else {
    showView("main");
  }
}

function setPickerChrome({ title, crumbs, search = false, footer = false, hint = "" }) {
  $("picker-title").textContent = title;
  $("picker-crumbs").textContent = crumbs || "";
  $("site-search").hidden = !search;
  $("picker-footer").hidden = !footer;
  $("picker-hint").textContent = hint;
}

async function fillList(loader, render, emptyText) {
  const list = $("picker-list");
  list.replaceChildren(el("li", "empty", "Loading…"));
  try {
    const items = await loader();
    list.replaceChildren();
    if (!items.length) list.append(el("li", "empty", emptyText));
    for (const item of items) list.append(render(item));
  } catch (error) {
    list.replaceChildren();
    showMessage(friendlyError(error));
  }
}

function listButton(main, sub, onClick) {
  const button = el("button", null, [el("span", null, main), sub ? el("span", "sub", sub) : null]);
  button.type = "button";
  button.addEventListener("click", onClick);
  return el("li", null, button);
}

// Step 1: site
function showSites() {
  state.picker = { step: "site", site: null, drive: null, folderStack: [] };
  setPickerChrome({ title: "Choose a site", search: true, hint: "Sites you follow:" });
  $("site-search-input").value = "";
  fillList(
    graph.getFollowedSites,
    (s) => listButton(s.displayName, s.webUrl, () => showLibraries(s)),
    "You don't follow any sites yet. Search for one above."
  );
}

function onSiteSearch(event) {
  event.preventDefault();
  const q = $("site-search-input").value.trim();
  if (!q) return showSites();
  $("picker-hint").textContent = `Results for “${q}”:`;
  fillList(
    () => graph.searchSites(q),
    (s) => listButton(s.displayName, s.webUrl, () => showLibraries(s)),
    "No sites found."
  );
}

// Step 2: library
function showLibraries(site) {
  state.picker = { step: "library", site, drive: null, folderStack: [] };
  setPickerChrome({ title: "Choose a library", crumbs: site.displayName });
  fillList(
    () => graph.getLibraries(site.id),
    (d) =>
      listButton(d.name, null, () => {
        state.picker.drive = d;
        showFolders();
      }),
    "This site has no document libraries you can access."
  );
}

// Step 3: folder
function showFolders() {
  const p = state.picker;
  p.step = "folder";
  const current = p.folderStack[p.folderStack.length - 1];
  setPickerChrome({
    title: current ? current.name : p.drive.name,
    crumbs: [p.site.displayName, p.drive.name, ...p.folderStack.map((f) => f.name)].join(" › "),
    footer: true,
    hint: "Open a folder, or save here:",
  });
  fillList(
    () => graph.getFolders(p.drive.id, current && current.id),
    (f) =>
      listButton(`📁 ${f.name}`, null, () => {
        p.folderStack.push({ id: f.id, name: f.name });
        showFolders();
      }),
    "No subfolders."
  );
}

async function onNewFolder() {
  const p = state.picker;
  const name = await promptInline("New folder name");
  if (!name) return;
  const parent = p.folderStack[p.folderStack.length - 1];
  try {
    const folder = await graph.createFolder(p.drive.id, parent && parent.id, name);
    p.folderStack.push({ id: folder.id, name: folder.name });
    showFolders();
  } catch (error) {
    showMessage(friendlyError(error));
  }
}

function onChooseFolder() {
  const p = state.picker;
  const current = p.folderStack[p.folderStack.length - 1];
  state.destination = {
    siteId: p.site.id,
    siteName: p.site.displayName,
    driveId: p.drive.id,
    driveName: p.drive.name,
    folderId: current ? current.id : null,
    folderPath: p.folderStack.map((f) => f.name),
  };
  setSetting("destination", state.destination);
  renderDestination();
  showView("main");
}

/** window.prompt isn't available in add-ins, so ask inline in the list. */
function promptInline(label) {
  return new Promise((resolve) => {
    const input = el("input");
    input.type = "text";
    input.placeholder = label;
    const ok = el("button", "secondary", "Create");
    ok.type = "submit";
    const cancel = el("button", "secondary", "Cancel");
    cancel.type = "button";
    const form = el("form", "search", [input, ok, cancel]);
    const li = el("li", null, form);
    li.style.padding = "8px 0";
    $("picker-list").prepend(li);
    input.focus();

    const done = (value) => {
      li.remove();
      resolve(value);
    };
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      done(input.value.trim().replace(/["*:<>?/\\|]/g, "_"));
    });
    cancel.addEventListener("click", () => done(null));
  });
}

/* ---------- Small DOM helpers ---------- */

function el(tag, className, children) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (children !== undefined && children !== null) {
    for (const child of [].concat(children)) {
      if (child === null || child === undefined) continue;
      node.append(typeof child === "string" ? document.createTextNode(child) : child);
    }
  }
  return node;
}

function link(text, href) {
  const a = el("a", null, text);
  a.href = href;
  a.target = "_blank";
  a.rel = "noopener";
  return a;
}

function showMessage(text) {
  const m = $("message");
  m.textContent = text;
  m.hidden = false;
}

function hideMessage() {
  $("message").hidden = true;
}
